from torch import nn
torch.set_num_threads(1)

def make_matches():
    return [{"match":m,"cards":[(m+t)%8 for t in range(24)]} for m in range(12)]

def windows(cards, width=2):
    return [(cards[i-width:i],cards[i]) for i in range(width,len(cards))]

def make_splits(matches):
    groups={"train":[],"validation":[],"test":[]}
    for match in matches:
        name="train" if match["match"]<8 else ("validation" if match["match"]<10 else "test")
        groups[name].append(match)
    return groups

def tensors(matches):
    rows=[row for match in matches for row in windows(match["cards"])]
    x=torch.tensor([history for history,label in rows],dtype=torch.long)
    y=torch.tensor([label for history,label in rows],dtype=torch.long)
    return x,y

class NextCard(nn.Module):
    def __init__(self,width):
        super().__init__()
        self.embedding=nn.Embedding(8,width)
        self.output=nn.Linear(2*width,8)
    def forward(self,x):
        return self.output(self.embedding(x).flatten(start_dim=1))

def train_model(width, train_matches, steps=100):
    torch.manual_seed(11)
    model=NextCard(width)
    x,y=tensors(train_matches)
    opt=torch.optim.Adam(model.parameters(),lr=0.05)
    model.train()
    for _ in range(steps):
        opt.zero_grad()
        loss=nn.functional.cross_entropy(model(x),y)
        loss.backward()
        opt.step()
    return model

def evaluate(model, matches):
    x,y=tensors(matches)
    model.eval()
    with torch.no_grad():
        logits=model(x)
        return {"accuracy":(logits.argmax(dim=1)==y).float().mean().item(),
                "nll":nn.functional.cross_entropy(logits,y).item(),"rows":len(y)}

def compare_sizes():
    g=make_splits(make_matches());rows=[];models={}
    for width in [4,8]:
        m=train_model(width,g['train']);models[width]=m
        s=evaluate(m,g['validation'])
        rows.append({'width':width,'params':sum(p.numel() for p in m.parameters()),'accuracy':s['accuracy'],'nll':s['nll']})
    chosen=min(rows,key=lambda r:(r['nll'],r['params']))['width']
    return {'validation':rows,'chosen_width':chosen,'test':evaluate(models[chosen],g['test'])}

